func main(){s:=m.NewReloadSync();if s==nil{panic("nil coordinator")};v,e:=m.NewMediaPlaylist(0,4);if e!=nil{panic(e)};v.SeqNo=100;if e=v.Append("v100.ts",1,"");e!=nil{panic(e)};msn,part:=uint64(700),uint64(0);v.RenditionReports=[]m.RenditionReport{{URI:"audio.m3u8?lang=zh&_HLS_part=8",LastMSN:&msn,LastPart:&part}};a,e:=m.NewMediaPlaylist(0,4);if e!=nil{panic(e)};a.SeqNo=700;a.CanBlockReload=true;source:="https://example.invalid/video.m3u8";target:="https://example.invalid/audio.m3u8?lang=zh&_HLS_part=8";if e=s.Update(source,v);e!=nil{panic(e)};if e=s.Update(target,a);e!=nil{panic(e)};r,e:=s.Plan(source,target);if e!=nil||r.Token==0||r.MSN!=700||r.Part==nil||*r.Part!=1{panic("explicit report next-part cursor")};u,e:=url.Parse(r.URL);if e!=nil||u.Query().Get("lang")!="zh"||u.Query().Get("_HLS_msn")!="700"||u.Query().Get("_HLS_part")!="1"{panic("reload query mismatch")};response,e:=m.NewMediaPlaylist(0,4);if e!=nil{panic(e)};response.SeqNo=700;response.CanBlockReload=true;response.TrailingParts=[]m.Part{{URI:"a0.m4s",Duration:0.25},{URI:"a1.m4s",Duration:0.25}};if e=s.Commit(r.Token,response);e!=nil{panic(e)};if s.Abort(r.Token)==nil{panic("committed token remained active")};next,e:=s.Plan(source,target);if e!=nil||next.Token==0||next.Token==r.Token{panic("next token")};if e=s.Abort(next.Token);e!=nil{panic(e)};fmt.Println("reload API consumer: ok")}
